(function() {
    'use strict';

    class IpFortressAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'IP Fortress';
            this.version = '1.1.0';

            this.ROUNDS = [
                { strategies: ['litigate_npe', 'ipr_npe', 'license_npe', 'buy_npe'] },
                { strategies: ['opensource_full', 'opensource_community', 'opensource_delay', 'opensource_decline'] },
                { strategies: ['portfolio_maintain', 'portfolio_lapse', 'portfolio_challenge', 'portfolio_designaround'] },
                { strategies: ['standards_sep', 'standards_nosep', 'standards_decline', 'standards_pledge'] },
                { strategies: ['ma_full', 'ma_selective', 'ma_reps', 'ma_accept'] }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ipBudget: 1200,
                    ipValueScore: 11200,
                    competitiveMoat: 62,
                    portfolioHealth: 71,
                    licensingRevenue: 280,
                    enterpriseValue: 68000,
                    totalLegalCosts: 0,
                    totalLicensingIncome: 280,
                    npeResolved: false,
                    openSourced: false,
                    tradeSecretProtected: false,
                    sepDeclared: false,
                    ivsHistory: [],
                    cmsHistory: [],
                    phsHistory: [],
                    lrrHistory: [],
                    evHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 'ipr_npe',
                    litigation: 200,
                    filing: 200,
                    licensing: 300,
                    security: 250,
                    innovation: 250
                };
            }
            this._updateBriefing(state);
            this._setupBudgetListener();
        }

        _setupBudgetListener() {
            var inputs = ['litigationInput', 'filingInput', 'licensingInput', 'securityInput', 'innovationInput'];
            var self = this;
            inputs.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        self._updateBudgetTotal();
                    });
                }
            });
        }

        _updateBudgetTotal() {
            var lit = parseFloat(document.getElementById('litigationInput').value) || 0;
            var fil = parseFloat(document.getElementById('filingInput').value) || 0;
            var lic = parseFloat(document.getElementById('licensingInput').value) || 0;
            var sec = parseFloat(document.getElementById('securityInput').value) || 0;
            var inn = parseFloat(document.getElementById('innovationInput').value) || 0;
            var total = lit + fil + lic + sec + inn;
            var el = document.getElementById('totalAllocated');
            if (el) {
                el.textContent = Math.round(total).toLocaleString();
                el.style.color = total > 1200 ? '#e74c3c' : '#f1c40f';
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;
            var t = (window.mySimulation && window.mySimulation.t) ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = '<strong>' + t('r' + n + '_title') + '</strong><br><br>' + t('r' + n + '_desc');

            var selectEl = document.getElementById('strategySelect');
            if (selectEl) {
                selectEl.innerHTML = '';
                round.strategies.forEach(function(val, i) {
                    var opt = document.createElement('option');
                    opt.value = val;
                    opt.textContent = t('r' + n + '_s' + (i + 1) + '_text');
                    selectEl.appendChild(opt);
                });
                selectEl.onchange = function() {
                    var hintEl = document.getElementById('strategyHint');
                    var si = round.strategies.indexOf(selectEl.value);
                    if (hintEl && si >= 0) hintEl.textContent = t('r' + n + '_s' + (si + 1) + '_hint');
                };
                var hintEl = document.getElementById('strategyHint');
                if (hintEl && round.strategies.length > 0) hintEl.textContent = t('r' + n + '_s1_hint');
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var strategyEl = document.getElementById('strategySelect');
            if (strategyEl) decisions.strategy = strategyEl.value;

            var litEl = document.getElementById('litigationInput');
            if (litEl) decisions.litigation = parseFloat(litEl.value) || 0;
            var filEl = document.getElementById('filingInput');
            if (filEl) decisions.filing = parseFloat(filEl.value) || 0;
            var licEl = document.getElementById('licensingInput');
            if (licEl) decisions.licensing = parseFloat(licEl.value) || 0;
            var secEl = document.getElementById('securityInput');
            if (secEl) decisions.security = parseFloat(secEl.value) || 0;
            var innEl = document.getElementById('innovationInput');
            if (innEl) decisions.innovation = parseFloat(innEl.value) || 0;

            var total = decisions.litigation + decisions.filing + decisions.licensing + decisions.security + decisions.innovation;

            if (total > 1200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            if (total < 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_minimum'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var ivsChange = 0;
            var cmsChange = 0;
            var phsChange = 0;
            var lrrChange = 0;
            var legalCost = 0;
            var strategyBonus = '';

            var litEffect = d.litigation / 100;
            var filEffect = d.filing / 100;
            var licEffect = d.licensing / 100;
            var secEffect = d.security / 100;
            var innEffect = d.innovation / 100;

            ivsChange += filEffect * 180;
            ivsChange += innEffect * 120;
            cmsChange += litEffect * 1.5;
            cmsChange += filEffect * 0.8;
            cmsChange += secEffect * 1.2;
            cmsChange += innEffect * 0.6;
            phsChange += secEffect * 1.8;
            phsChange += filEffect * 0.6;
            phsChange += licEffect * 0.4;
            lrrChange += licEffect * 55;

            legalCost = d.litigation + d.filing + d.licensing + d.security + d.innovation;

            if (round === 1) {
                if (d.strategy === 'litigate_npe') {
                    legalCost += 380;
                    cmsChange += 6;
                    ivsChange += 300;
                    strategyBonus = 'Filed litigation against QuantumIP. Strong deterrent signal.';
                } else if (d.strategy === 'ipr_npe') {
                    legalCost += 140;
                    cmsChange += 4;
                    ivsChange += 400;
                    phsChange += 2;
                    strategyBonus = 'IPR petition filed at PTAB. Cost-efficient challenge to patent validity.';
                    ds.npeResolved = true;
                } else if (d.strategy === 'license_npe') {
                    legalCost += 900;
                    cmsChange -= 2;
                    ivsChange -= 200;
                    strategyBonus = 'Licensed from QuantumIP. Fast resolution but precedent set for future trolls.';
                    ds.npeResolved = true;
                } else if (d.strategy === 'buy_npe') {
                    legalCost += 1500;
                    cmsChange += 5;
                    ivsChange += 600;
                    phsChange += 3;
                    strategyBonus = 'Acquired full QuantumIP portfolio. Threat neutralized, defensive patents gained.';
                    ds.npeResolved = true;
                }
            } else if (round === 2) {
                if (d.strategy === 'opensource_full') {
                    cmsChange += 3;
                    phsChange += 8;
                    ivsChange -= 400;
                    lrrChange += 120;
                    ds.openSourced = true;
                    strategyBonus = 'VeloxCore released under Apache 2.0. Developer community surges. Long-term ecosystem value.';
                } else if (d.strategy === 'opensource_community') {
                    cmsChange += 1;
                    phsChange += 4;
                    lrrChange += 60;
                    strategyBonus = 'Community License offered. Moderate goodwill, commercial exclusivity preserved.';
                } else if (d.strategy === 'opensource_delay') {
                    phsChange += 2;
                    strategyBonus = 'Advisory Board established. Buys time but fork threat remains.';
                } else if (d.strategy === 'opensource_decline') {
                    cmsChange -= 3;
                    ivsChange -= 200;
                    strategyBonus = 'Declined to open-source. Fork campaign accelerated. VeloxFree project launched.';
                }
                lrrChange += 190;
            } else if (round === 3) {
                if (d.strategy === 'portfolio_maintain') {
                    legalCost += 74;
                    phsChange += 5;
                    cmsChange += 2;
                    ivsChange += 200;
                    strategyBonus = 'Full portfolio maintained. FTO clearance completed for v5.0.';
                } else if (d.strategy === 'portfolio_lapse') {
                    ivsChange -= 100;
                    phsChange += 2;
                    cmsChange += 1;
                    lrrChange += 34;
                    strategyBonus = 'Low-value patents lapsed. Budget freed for higher-value investments.';
                } else if (d.strategy === 'portfolio_challenge') {
                    legalCost += 50;
                    cmsChange += 6;
                    ivsChange += 350;
                    strategyBonus = 'EPO opposition filed against competitor patent. Protecting core technology space.';
                } else if (d.strategy === 'portfolio_designaround') {
                    legalCost += 40;
                    cmsChange += 3;
                    phsChange += 3;
                    strategyBonus = 'Design-around completed. FTO secured through engineering, not litigation.';
                }
                lrrChange += 140;
            } else if (round === 4) {
                if (d.strategy === 'standards_sep') {
                    cmsChange += 10;
                    ivsChange += 800;
                    phsChange += 4;
                    lrrChange -= 50;
                    ds.sepDeclared = true;
                    strategyBonus = 'SEP declared with FRAND. Major influence on industry standard. Licensing constrained but moat strengthened.';
                } else if (d.strategy === 'standards_nosep') {
                    cmsChange += 5;
                    ivsChange += 300;
                    phsChange += 2;
                    strategyBonus = 'Consortium participation without SEP. Flexibility maintained, moderate influence.';
                } else if (d.strategy === 'standards_decline') {
                    cmsChange -= 2;
                    ivsChange -= 100;
                    strategyBonus = 'Declined consortium. Full autonomy preserved but standard develops without you.';
                } else if (d.strategy === 'standards_pledge') {
                    cmsChange += 7;
                    ivsChange += 500;
                    phsChange += 6;
                    strategyBonus = 'Defensive Patent Pledge offered. Strong ecosystem signal. Assertion rights preserved against competitors.';
                }
                lrrChange += 80;
            } else if (round === 5) {
                if (d.strategy === 'ma_full') {
                    legalCost += 200;
                    phsChange += 15;
                    ivsChange += 1200;
                    cmsChange += 3;
                    strategyBonus = 'Full remediation completed. Acquirer confidence maximized. Premium valuation.';
                } else if (d.strategy === 'ma_selective') {
                    legalCost += 80;
                    phsChange += 8;
                    ivsChange += 600;
                    strategyBonus = 'Critical gaps fixed. Minor issues remain for negotiation. Good valuation.';
                } else if (d.strategy === 'ma_reps') {
                    phsChange += 2;
                    ivsChange -= 300;
                    strategyBonus = 'Broader reps offered instead of fixes. Acquirer demands escrow and price adjustment.';
                } else if (d.strategy === 'ma_accept') {
                    ivsChange -= 1200;
                    phsChange -= 3;
                    strategyBonus = 'Accepted IP discount. Enterprise value reduced by acquirer risk assessment.';
                }
                lrrChange += 50;
            }

            if (ds.openSourced && round >= 3) {
                ivsChange += 200;
                lrrChange += 40;
            }
            if (ds.npeResolved && round >= 2) {
                cmsChange += 1;
            }

            ds.ipValueScore = Math.max(5000, ds.ipValueScore + ivsChange);
            ds.competitiveMoat = Math.max(0, Math.min(100, ds.competitiveMoat + cmsChange));
            ds.portfolioHealth = Math.max(0, Math.min(100, ds.portfolioHealth + phsChange));
            ds.licensingRevenue = Math.max(0, ds.licensingRevenue + lrrChange);
            ds.totalLegalCosts += legalCost;
            ds.totalLicensingIncome += ds.licensingRevenue;

            var ebitda = 5320 + (ds.licensingRevenue * 0.9);
            var ipMultiplier = 1.0 + ((ds.portfolioHealth - 50) / 200) + ((ds.competitiveMoat - 50) / 250);
            var baseEV = ebitda * 11 * ipMultiplier;
            var ipContribution = ds.ipValueScore * 1.2;
            var strategicPremium = 1.0;
            if (ds.competitiveMoat > 75) strategicPremium += 0.15;
            if (ds.sepDeclared) strategicPremium += 0.08;
            if (ds.openSourced && ds.competitiveMoat > 60) strategicPremium += 0.05;
            ds.enterpriseValue = Math.round((baseEV + ipContribution) * strategicPremium);

            ds.ivsHistory.push(ds.ipValueScore);
            ds.cmsHistory.push(ds.competitiveMoat);
            ds.phsHistory.push(ds.portfolioHealth);
            ds.lrrHistory.push(ds.licensingRevenue);
            ds.evHistory.push(ds.enterpriseValue);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                strategy: d.strategy,
                strategyBonus: strategyBonus,
                budgetUsed: legalCost,
                ivsChange: ivsChange,
                cmsChange: Math.round(cmsChange * 10) / 10,
                phsChange: Math.round(phsChange * 10) / 10,
                lrrChange: lrrChange,
                ipValueScore: ds.ipValueScore,
                competitiveMoat: Math.round(ds.competitiveMoat * 10) / 10,
                portfolioHealth: Math.round(ds.portfolioHealth * 10) / 10,
                licensingRevenue: ds.licensingRevenue,
                enterpriseValue: ds.enterpriseValue
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.ipBudget',
                (v) => Math.round(v).toLocaleString() + 'K');
            uiManager.bind('ivsDisplay', 'domainState.ipValueScore',
                (v) => (v / 1000).toFixed(1) + 'M');
            uiManager.bind('cmsDisplay', 'domainState.competitiveMoat',
                (v) => Math.round(v) + '/100');
            uiManager.bind('phsDisplay', 'domainState.portfolioHealth',
                (v) => Math.round(v) + '/100');
            uiManager.bind('lrrDisplay', 'domainState.licensingRevenue',
                (v) => Math.round(v).toLocaleString() + 'K/yr');
            uiManager.bind('evDisplay', 'domainState.enterpriseValue',
                (v) => (v / 1000).toFixed(1) + 'M');
        }

        getChartConfig() {
            return {
                valueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'IP Value Score (K)',
                            data: [],
                            borderColor: '#2ecc71',
                            backgroundColor: 'rgba(46,204,113,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y'
                        }, {
                            label: 'Enterprise Value (K)',
                            data: [],
                            borderColor: '#9b59b6',
                            backgroundColor: 'rgba(155,89,182,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            yAxisID: 'y1'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: '#c0c0e0' } }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                position: 'left',
                                beginAtZero: false,
                                ticks: { color: '#2ecc71' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            },
                            y1: {
                                type: 'linear',
                                position: 'right',
                                beginAtZero: false,
                                ticks: { color: '#9b59b6' },
                                grid: { drawOnChartArea: false }
                            },
                            x: {
                                ticks: { color: '#b0b0d0' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            }
                        }
                    }
                },
                moatChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Competitive Moat',
                            data: [],
                            borderColor: '#3498db',
                            backgroundColor: 'rgba(52,152,219,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Portfolio Health',
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: '#c0c0e0' } }
                        },
                        scales: {
                            y: {
                                min: 0,
                                max: 100,
                                ticks: { color: '#b0b0d0' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            },
                            x: {
                                ticks: { color: '#b0b0d0' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.ivsHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ivsHistory },
                        { data: state.domainState.evHistory }
                    ]
                },
                moatChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.cmsHistory },
                        { data: state.domainState.phsHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var ev = lastResult.enterpriseValue || 0;
            var cms = lastResult.competitiveMoat || 0;
            var phs = lastResult.portfolioHealth || 0;
            var ivs = lastResult.ipValueScore || 0;

            var ivsPoints = 0;
            if (ivs >= 18000) ivsPoints = 50;
            else if (ivs >= 14000) ivsPoints = 30 + ((ivs - 14000) / 4000) * 20;
            else if (ivs >= 11000) ivsPoints = 15 + ((ivs - 11000) / 3000) * 15;
            else ivsPoints = Math.max(5, (ivs / 11000) * 15);

            var cmsPoints = 0;
            if (cms >= 78) cmsPoints = 40;
            else cmsPoints = (cms / 78) * 40;

            var phsPoints = 0;
            if (phs >= 85) phsPoints = 30;
            else phsPoints = (phs / 85) * 30;

            var totalScore = Math.round(ivsPoints + cmsPoints + phsPoints);

            var performance = 'Developing IP Strategist';
            if (totalScore >= 100) performance = 'Master IP Strategist';
            else if (totalScore >= 80) performance = 'Senior IP Strategist';
            else if (totalScore >= 60) performance = 'Competent IP Strategist';

            var insights = [];
            if (ivs >= 16000) insights.push('Strong IP value creation through filing and licensing.');
            if (ivs < 12000) insights.push('IP value deteriorated. Consider more aggressive filing and licensing.');
            if (cms >= 75) insights.push('Excellent competitive moat built through strategic IP protection.');
            if (cms < 55) insights.push('Competitive moat weakened. Invest more in litigation and security.');
            if (phs >= 82) insights.push('Portfolio health is strong. Well-prepared for M and A.');
            if (phs < 65) insights.push('Portfolio health needs attention. Documentation gaps affect valuation.');
            if (ev >= 90000) insights.push('Enterprise valuation in premium range. Excellent IP strategy execution.');
            if (ev < 65000) insights.push('Enterprise value below baseline. IP decisions have eroded company value.');

            return {
                totalScore: totalScore,
                maxScore: 120,
                enterpriseValue: ev,
                ipValueScore: ivs,
                competitiveMoat: cms,
                portfolioHealth: phs,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cmsChange < 0) return window.mySimulation.t('hint_moat_declining');
            if (results.phsChange < 0) return window.mySimulation.t('hint_health_declining');
            if (results.budgetUsed > 1100) return window.mySimulation.t('hint_budget_high');
            if (results.ivsChange > 500) return window.mySimulation.t('hint_ivs_great');
            if (state.domainState.competitiveMoat < 55) return window.mySimulation.t('hint_moat_low');
            if (state.domainState.portfolioHealth < 60) return window.mySimulation.t('hint_health_low');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.strategy', label: 'Strategy', i18nKey: 'col_strategy' },
                { key: 'results.budgetUsed', label: 'Cost (K)', i18nKey: 'col_cost', formatter: (v) => Math.round(v).toLocaleString() + 'K' },
                { key: 'results.ipValueScore', label: 'IVS (K)', i18nKey: 'col_ivs', formatter: (v) => (v / 1000).toFixed(1) + 'M' },
                { key: 'results.competitiveMoat', label: 'Moat', i18nKey: 'col_moat', formatter: (v) => Math.round(v) + '/100' },
                { key: 'results.portfolioHealth', label: 'Health', i18nKey: 'col_health', formatter: (v) => Math.round(v) + '/100' },
                { key: 'results.licensingRevenue', label: 'LRR (K/yr)', i18nKey: 'col_lrr', formatter: (v) => Math.round(v).toLocaleString() + 'K' },
                { key: 'results.enterpriseValue', label: 'EV (K)', i18nKey: 'col_ev', formatter: (v) => (v / 1000).toFixed(1) + 'M' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    r1_title: `Round 1 — Threat Triage and Immediate Response (Months 1-6)`,
                    r1_desc: `Velox Systems faces a perfect storm: <b>QuantumIP Holdings</b> (a patent troll) demands a license at $3.2M for 3 edge-computing patents. <b>Komatsu Industrial Systems</b> proposes a major OEM license deal. <b>340 developers</b> demand VeloxCore be open-sourced. <b>Elena Mueller</b>, a senior engineer, departed with 4.7 GB of trade-secret data to competitor Nexion AI.<br><br>Your annual IP budget is 1,200K. These four crises collectively require up to 3,500K to address fully. Prioritize ruthlessly.`,
                    r1_s1_text: `Litigate against QuantumIP (fight on merits in court)`,
                    r1_s1_hint: `High cost (380K retainer), 24-36 months, strong deterrent but risky.`,
                    r1_s2_text: `File IPR petition at PTAB (challenge patent validity)`,
                    r1_s2_hint: `Moderate cost (140K), 12-18 months, 60-70% institution rate. Efficient.`,
                    r1_s3_text: `Negotiate license with QuantumIP (settle quickly)`,
                    r1_s3_hint: `Cost 600K-1,200K, fast resolution, but sets precedent inviting future trolls.`,
                    r1_s4_text: `Buy the entire QuantumIP patent portfolio`,
                    r1_s4_hint: `Cost 1,200K-1,800K, permanently neutralizes threat, gains defensive patents.`,
                    r2_title: `Round 2 — Strategic Positioning (Months 7-12)`,
                    r2_desc: `Round 1 consequences unfold. The Komatsu license advances to term-sheet stage. A <b>new cross-licensing approach</b> from a tier-1 automotive OEM presents 12 patents in your technology space. The VeloxCore developer community grows restless. The trade-secret investigation reveals Nexion AI is filing suspiciously similar patents.<br><br>Decide your open-source and licensing strategy.`,
                    r2_s1_text: `Open-source VeloxCore under Apache 2.0`,
                    r2_s1_hint: `Big ecosystem boost, developer goodwill, but risks patent exhaustion and licensing revenue.`,
                    r2_s2_text: `Offer a free Community License (non-commercial only)`,
                    r2_s2_hint: `Moderate goodwill, preserves commercial exclusivity. Developers may still fork.`,
                    r2_s3_text: `Establish a Community Advisory Board (delay decision)`,
                    r2_s3_hint: `Buys time but does not resolve the fork threat. Community patience wears thin.`,
                    r2_s4_text: `Decline to open-source VeloxCore`,
                    r2_s4_hint: `Preserves IP fully but fork campaign accelerates. Competitive alternative likely within 12 months.`,
                    r3_title: `Round 3 — Portfolio Optimization (Months 13-18)`,
                    r3_desc: `Three low-value patents approach renewal deadlines. A <b>European competitor</b> has filed patents overlapping your anomaly-detection technology (P-003). <b>Hyundai Robotics</b> (South Korea) requests a non-exclusive license for logistics automation. VeloxEdge v5.0 needs a freedom-to-operate clearance.<br><br>Optimize your portfolio: what to maintain, what to lapse, what to challenge.`,
                    r3_s1_text: `Maintain all patents and file FTO clearance study`,
                    r3_s1_hint: `Safe but expensive. 34K in maintenance plus 40K FTO study. Full coverage.`,
                    r3_s2_text: `Lapse low-value patents (P-004, P-006) and redirect budget`,
                    r3_s2_hint: `Saves 34K/year. Freed budget can fund competitor challenge or new filings.`,
                    r3_s3_text: `Challenge European competitor patent at EPO`,
